mapper.select:
/* LinkKeyMapper.selectLinkKeyList 연계기관의 클라이언트 키 목록을 상태·발급일시 최근 순으로 조회 (암호화 비밀키 제외) */
SELECT 
FROM TB_LNK_KEY_M
WHERE LNK_ORG_ID = #{lnkOrgId}
ORDER BY KEY_STAT_CD, TB_LNK_KEY_M.ISSU_DTTM DESC

/* LinkKeyMapper.selectLinkKey 연계기관의 클라이언트 키 1건을 조회 (암호화 비밀키 제외) */
SELECT 
FROM TB_LNK_KEY_M
WHERE LNK_ORG_ID = #{lnkOrgId}
  AND KEY_ID = #{keyId}

mapper.insert:
/* LinkKeyMapper.insertLinkKey 클라이언트 키를 사용 상태로 등록 */
INSERT INTO TB_LNK_KEY_M (
    KEY_ID, LNK_ORG_ID, ENC_KEY_VAL, KMS_KEY_ID, KEY_STAT_CD, ISSU_DTTM, EXPI_DTTM,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{keyId}, #{lnkOrgId}, #{encKeyVal}, #{kmsKeyId}, '01', #{issuDttm}, #{expiDttm},
    #{usrId}, CURRENT_TIMESTAMP, #{usrId}, CURRENT_TIMESTAMP
)

/* LinkKeyMapper.insertLinkKeyHist 클라이언트 키 이력을 등록 */
INSERT INTO TB_LNK_KEY_H (
    KEY_HIST_SN, KEY_ID, KEY_STAT_CD, CHG_CONT, KMS_AUDIT_ID,
    FIRS_REGR_ID, FIRS_REG_DT
) VALUES (
    NEXTVAL('SQ_TB_LNK_KEY_H_KEY_HIST_SN'), #{keyId}, #{keyStatCd}, #{chgCont}, #{kmsAuditId},
    #{usrId}, CURRENT_TIMESTAMP
)
